function marketStats(rows){const tr=rows.filter(r=>!CONFIG.stable.has(r.symbol));const breadth=tr.length?tr.filter(r=>num(r.price_change_percentage_24h)>=0).length/tr.length*100:50;const btc=rows.find(r=>r.symbol==='btc')||tr[0],eth=rows.find(r=>r.symbol==='eth')||tr[1],b24=num(btc?.price_change_percentage_24h),e24=num(eth?.price_change_percentage_24h),avg7=tr.length?tr.reduce((a,r)=>a+num(r.price_change_percentage_7d_in_currency),0)/tr.length:0,vol=tr.length?tr.reduce((a,r)=>a+Math.abs(num(r.price_change_percentage_24h)),0)/tr.length:0;let label='RANGE / MIXTE',base=60;if(breadth>62&&b24>1){label='RISK-ON';base=80}else if(breadth<38&&b24<-1){label='RISK-OFF';base=42}else if(Math.abs(b24)<.8&&Math.abs(avg7)<2){label='MARCHÉ PLAT';base=55}else if(e24>b24+1&&breadth>55){label='ROTATION ALTCOINS';base=77}if(vol>5)label+=' • VOLATIL';return{breadth,btc,eth,b24,e24,avg7,vol,label,base}}
function scoreAsset(r,m){const h1=num(r.price_change_percentage_1h_in_currency),d1=num(r.price_change_percentage_24h),d7=num(r.price_change_percentage_7d_in_currency),d30=num(r.price_change_percentage_30d_in_currency),vmc=num(r.total_volume)/Math.max(num(r.market_cap),1),rank=num(r.market_cap_rank,300),ath=num(r.ath_change_percentage,-50);const volume=clamp(35+Math.log10(Math.max(vmc,.0001)*10000)*14),stability=clamp(88-Math.abs(d1)*2.2-Math.max(0,Math.abs(h1)-3)*3.2),cap=clamp(94-Math.log10(Math.max(rank,1))*19),liquidity=clamp(35+Math.log10(Math.max(num(r.total_volume),1))*5.3),recovery=clamp(90+ath*.4),fund=clamp(cap*.45+liquidity*.35+recovery*.2);const lm=clamp(50+h1*8+d1*2.8+d7*.8),sm=clamp(50-h1*8-d1*2.8-d7*.8),lt=clamp(50+d1*2+d7*1.2+d30*.28),st=clamp(50-d1*2-d7*1.2-d30*.28),longTech=clamp(lm*.36+lt*.34+volume*.2+stability*.1),shortTech=clamp(sm*.36+st*.34+volume*.2+stability*.1),longQuant=clamp(longTech*.42+volume*.22+stability*.16+liquidity*.12+recovery*.08),shortQuant=clamp(shortTech*.42+volume*.22+stability*.16+liquidity*.12+recovery*.08);const rel=d1-num(m.b24),longRegime=clamp(m.base+rel*2.4+(m.breadth-50)*.25),shortRegime=clamp((100-m.base)+(-rel)*2.2+(50-m.breadth)*.35+Math.max(0,-num(m.b24))*2.2),la=clamp(50+h1*10+(d1-h1*4)*3),sa=clamp(50-h1*10-(d1-h1*4)*3),longFomo=clamp(la*.36+volume*.2+longTech*.18+longQuant*.12+longRegime*.14),shortFomo=clamp(sa*.36+volume*.2+shortTech*.18+shortQuant*.12+shortRegime*.14),pen=Math.max(0,Math.abs(d1)-11)*1.1+Math.max(0,Math.abs(h1)-6)*1.6,longAi=clamp(longTech*.24+longQuant*.2+fund*.18+longRegime*.2+longFomo*.18-pen),shortAi=clamp(shortTech*.24+shortQuant*.2+fund*.18+shortRegime*.2+shortFomo*.18-pen);const preferredSide=shortAi>longAi?'short':'long',tech=preferredSide==='short'?shortTech:longTech,quant=preferredSide==='short'?shortQuant:longQuant,regime=preferredSide==='short'?shortRegime:longRegime,fomo=preferredSide==='short'?shortFomo:longFomo,ai=preferredSide==='short'?shortAi:longAi,volPct=clamp(Math.abs(h1)*.9+Math.abs(d1)*.32+Math.abs(d7)*.08+1.25,1.6,10.5),risk=clamp(ai*.36+quant*.2+regime*.2+fund*.12+liquidity*.12-Math.max(0,volPct-6)*3),edge=Math.abs(longAi-shortAi),opportunity=clamp(ai*.7+fomo*.22+risk*.08),price=num(r.current_price)/Math.max(state.fx.usdtUsd,.000001);let status='neutral',label='NEUTRE';if(ai>=80&&fomo>=73&&regime>=52){status='order';label='ORDRE CONSEILLÉ'}else if(ai>=72&&fomo>=62){status='preorder';label='PRÉ-ORDRE'}else if(ai>=62){status='watch';label='À SURVEILLER'}const reason=[preferredSide.toUpperCase(),tech>72?'momentum solide':'momentum moyen',quant>72?'Quant robuste':'Quant à confirmer',regime>68?'régime favorable':'régime mixte',edge>8?'avantage directionnel net':'edge modéré'].join(' • ');return{...r,currentPriceUSDT:price,tech,quant,fund,regime,fomo,ai,risk,longAi,shortAi,longTech,shortTech,longRegime,shortRegime,longFomo,shortFomo,preferredSide,directionEdge:edge,opportunityScore:opportunity,volatilityPricePct:volPct,status,label,reason,entryLow:price*.997,entryHigh:price*1.002}}
function chooseSide(a){return a?.preferredSide==='short'?'short':'long'}
function rankOf(a){const i=state.ranked.findIndex(x=>x.id===a?.id);return i>=0?i+1:null}
function positionByAsset(id){return state.positions.find(p=>p.assetId===id)}
function recentClosed(id){return state.closed.some(p=>p.assetId===id&&Date.now()-new Date(p.closedAt).getTime()<CONFIG.reentryCooldownMinutes*60000)}
function horizonMinutes(a){const structural=(num(a.quant)+num(a.fund)+num(a.regime))/3,v=num(a.volatilityPricePct);if(a.ai>=90&&a.fomo>=86&&v>5)return 360;if(a.ai>=85&&a.fomo>=78)return 720;if(a.ai>=80&&structural>=74)return 1440;if(structural>=70&&a.risk>=68)return 2880;if(a.ai>=70)return 4320;return 5760}
