function positionCalc(p){const entry=num(p.entryPriceUSDT),cur=num(p.currentPriceUSDT,entry),side=p.side==='short'?-1:1,qty=entry>0?CONFIG.stakeUSDT/entry:0,gross=qty*(cur-entry)*side,entryFee=fee(CONFIG.stakeUSDT,1),exitFee=fee(Math.max(0,qty*cur),1),net=gross-entryFee-exitFee,pnlPct=net/CONFIG.stakeUSDT*100,target=new Date(p.targetCloseAt).getTime(),remaining=Math.max(0,target-Date.now());return{entry,cur,qty,gross,entryFee,exitFee,net,pnlPct,remaining,due:Date.now()>=target}}
